/* Returns the uncalibrated model probability. features[] in DGX_ECG_FEATURE_NAMES order; NAN = missing. */
static inline double dgx_ecg_score(const float *features) {
    double x[DGX_ECG_N_FEATURES];
    for (int i = 0; i < DGX_ECG_N_FEATURES; ++i)
        x[i] = isnan(features[i]) ? DGX_ECG_MEDIAN[i] : (double)features[i];
    double raw = 0.0;
    for (int t = 0; t < DGX_ECG_N_TREES; ++t) {
        int32_t n = DGX_ECG_ROOT[t];
        while (n >= 0)
            n = (x[DGX_ECG_FEAT[n]] <= DGX_ECG_THR[n]) ? DGX_ECG_LEFT[n] : DGX_ECG_RIGHT[n];
        raw += DGX_ECG_LEAF[~n];
    }
    return 1.0 / (1.0 + exp(-raw));
}
